import os

def has_null_bytes(filepath):
    try:
        with open(filepath, 'rb') as f:
            content = f.read()
            return b'\\x00' in content
    except:
        return False

def find_corrupted_files(root_dir):
    corrupted = []
    for root, dirs, files in os.walk(root_dir):
        for file in files:
            if file.endswith('.py'):
                filepath = os.path.join(root, file)
                if has_null_bytes(filepath):
                    corrupted.append(filepath)
    return corrupted

corrupted = find_corrupted_files('scrapy')
for f in corrupted:
    print(f)
